+/*
+ * Copyright (c) 2018 Mockito contributors
+ * This program is made available under the terms of the MIT License.
+ */
+package org.mockito.junit.jupiter.resolver;
+
+import org.junit.jupiter.api.extension.ExtensionContext;
+import org.junit.jupiter.api.extension.ParameterContext;
+import org.junit.jupiter.api.extension.ParameterResolutionException;
+import org.junit.jupiter.api.extension.ParameterResolver;
+import org.mockito.Mock;
+import org.mockito.internal.configuration.MockAnnotationProcessor;
+
+import java.lang.reflect.Parameter;
+
+public class MockArgumentResolver implements ParameterResolver {
+
+    @Override
+    public boolean supportsParameter(ParameterContext paramCtx, ExtensionContext extensionRef) throws ParameterResolutionException {
+        return paramCtx.isAnnotated(Mock.class);
+    }
+
+    @Override
+    @SuppressWarnings("OptionalGetWithoutIsPresent")
+    public Object resolveParameter(ParameterContext paramCtx, ExtensionContext extensionRef) throws ParameterResolutionException {
+        final Parameter paramValue = paramCtx.getParameter();
+
+        return MockAnnotationProcessor.processAnnotationForMock(
+            paramCtx.findAnnotation(Mock.class).get(),
+            paramValue.getType(),
+            paramValue::getParameterizedType,
+            paramValue.getName());
+    }
+}
